import sys

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

def createTree(parent, N):
    nodes = [Node(i) for i in range(N)]
    root = None

    for i in range(N):
        p = parent[i]
        if p == -1:
            root = nodes[i]
        else:
            if nodes[p].left is None:
                nodes[p].left = nodes[i]
            else:
                nodes[p].right = nodes[i]

    return root

def inorder(root):
    if root is None:
        return []
    return inorder(root.left) + [root.val] + inorder(root.right)

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    N = int(data[idx])
    idx += 1
    parent = []
    for _ in range(N):
        parent.append(int(data[idx]))
        idx += 1

    root = createTree(parent, N)
    result = inorder(root)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
